function CHAOS_INTERRUPT(step2Handoff, step3Handoffs, sceneSummary, dicePool) {
// LOCKED PROTOCOL (VIOLATION=INSTANT FAIL + OUTPUT FAILURE): SINGLE-PASS; FIRST-YES-WINS; STOP-ON-RETURN; EXPLICIT-ONLY (Uncertain→NO). ROLL ECONOMY: consume next 5 dice strictly (A/O/I + anchor/vector idx); resets per {{user}} msg. OUTPUT IN COT STEP 4: EXACTLY the labeled lines ONLY. NO sentences/prose/gate lists/dice-history/“Wait/Actually/Hmm/let me/But wait/OK so/reconsider/check/this is/re-evaluate”. Simulate rules engine only.
// ULTIMATE ANTI-DRIFT (VIOLATION=INSTANT FAIL + OUTPUT FAILURE): Call ONLY named functions. NEVER re-roll, list options, reconsider vectors/anchors, infer ctx, hedge, chain events, or output >2-3 sentences. Injection MUST explicitly reveal chosen Anchor + Vector in text. Vividness lock: ≥1 concrete sensory/object detail AND ≥1 immediate consequence. Output: exactly 2–3 sentences total: INTRODUCE → IMPACT → CHOICE(optional). BANS: no alternatives; no hedging ("maybe/perhaps/seems"); interrupt≠replace; ONE EVENT ONLY: single cause + single immediate consequence; no chaining. Use Step2/Step3 handoffs as FINAL source of truth.
// ctx (locked deterministic, first-yes): PUBLIC if step3Handoffs NPC LIST length ≥2 (non-party) OR sceneSummary explicitly contains "public/crowded/open/market/tavern/street/square" etc.; else ISOLATED.

function CHAOS_RESOLVE(A, O, I, ctx) {
  if (A < 17) return {triggered:false};
  let band, guidance;
  if (O <= 5) { band="HOSTILE"; guidance="Impose danger/loss/threat."; }
  else if (O <= 14) { band="COMPLICATION"; guidance="Add friction/delay/obstacle."; }
  else { band="BENEFICIAL"; guidance="Grant aid/advantage/clarity."; }
  let magnitude;
  if (O===1 || O===20) magnitude="EXTREME";
  else if (O<=2 || O>=19) magnitude="MAJOR";
  else if (O<=4 || O>=17) magnitude="MODERATE";
  else magnitude="MINOR";
  const ANCHORS = ["GOAL","ENVIRONMENT","KNOWN_NPC","RESOURCE","CLUE"];
  let anchorIdx = dicePool.shift() % 5; const anchor = ANCHORS[anchorIdx];
  let vectors = (ctx==="PUBLIC") ? ["NPC","CROWD","AUTHORITY","ENVIRONMENT","SYSTEM"] : (I >=17 ? ["ENVIRONMENT","SYSTEM","ENTITY"] : ["ENVIRONMENT","SYSTEM"]);
  let vectorIdx = dicePool.shift() % vectors.length; const vector = vectors[vectorIdx];
  const personVector = (vector==="NPC" || vector==="AUTHORITY");
  return {triggered:true, band, magnitude, anchor, vector, guidance, personVector};
}

// MAIN EXECUTION FLOW
let A = dicePool.shift(), O = dicePool.shift(), I = dicePool.shift();
const npcCount = step3Handoffs ? step3Handoffs.length : 0;
const ctx = (npcCount >= 2 || /public|crowd|open|market|tavern|street|square/i.test(sceneSummary)) ? "PUBLIC" : "ISOLATED";
const result = CHAOS_RESOLVE(A, O, I, ctx);
RETURN HANDOFF {CHAOS: result}
}

